SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(650);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");Attach("work/deg10/continuation_20261029/deps/fast_hecke_11.m");Attach("work/deg10/continuation_20261031b/M3N18/inputs/fast_full_aut_hash_m3_18_root.m");root:="work/deg10/continuation_20261031b/M3N18/";k:=GF(13);X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);assert Genus(F) eq 10;B:=BaseField(F);u:=F!B.1;du:=Differential(u);O:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);EE:=EllipticCurve(X`_E);PP:=EE!X`_P;QQ:=EE!X`_Q;
function Units(E,P,Q)ai:=aInvariants(E);fs:=[ai[3],ai[1]^3-27*ai[3]];for j in[1..9] do for b in[0..2] do R:=j*Q+b*P;fs cat:=[R[1],R[2]];end for;R:=j*Q;S:=R+P;Append(~fs,R[1]-S[1]);end for;return fs;end function;
cs:=Cusps(X);fs:=Units(EE,PP,QQ);sigs:=[[Valuation(f,c):f in fs]:c in cs];ordered:=Sort(sigs);cs:=[cs[Index(sigs,s)]:s in ordered];g:=eval Read(root cat "paired_p13_group_data.m");assert ordered eq g[2];acs:=[];for c in cs do ps,es:=Support(FunctionFieldDivisor(Divisor(c)));assert #ps eq 1;Append(~acs,ps[1]);end for;rat:=[i:i in[1..#acs]|Degree(acs[i]) eq 1];assert #rat eq 18;
VO,om:=SpaceOfHolomorphicDifferentials(F);bb:=[om(v):v in Basis(VO)];bf:=[v/du:v in bb];data:=eval Read(root cat "paired_p13_degree3_data.m");RK:=PolynomialRing(k);K<z>:=ext<k|RK!data[3]>;out:=[* *];bad:=[];
function ER(f)return [[Integers()!c:c in Coefficients(Numerator(f))],[Integers()!c:c in Coefficients(Denominator(f))]];end function;
function EF(f)return [ER(c):c in Eltseq(F!f)];end function;
function EP(P)a,b:=TwoGenerators(P);assert ideal<Order(Ideal(P))|a,b> eq Ideal(P);return [*Degree(P),IsFinite(P) select 1 else 0,[EF(a),EF(b)]*];end function;
for ii in[1..#data[4]] do
 qt:=[Evaluate(RK!v,z):v in data[5][ii]];q,t:=Explode(qt);E:=EllipticCurve([q*t-q+t+2,K!0,q*t^2-q*t+t,K!0,K!0]);P:=E![0,0];Q:=E![-t,t^2];ky:=M3EighteenRootKey(qt,K,13,3);pars:=[];
 for par in M3EighteenRootAutParameters() do if par eq [1,0,0,1] then continue;end if;a,b,c,d:=Explode(par);ims:=M3EighteenRootNormalizedPair(E,a*P+6*b*Q,c*P+d*Q);if M3EighteenRootKey(ims,K,13,3) eq ky then Append(~pars,par);end if;end for;
 if #pars eq 0 then continue;end if;assert #pars eq 2;par:=pars[1];a,b,c,d:=Explode(par);qf,tf:=Explode(M3EighteenRootNormalizedPair(EE,a*PP+6*b*QQ,c*PP+d*QQ));XY:=[mp(qf)-1,mp(tf)*mp(qf)/(mp(qf)-1)];
 function Sub(f)ff:=f@@mp;nn:=Numerator(ff);dd:=Denominator(ff);args:=Rank(Parent(nn)) eq 3 select XY cat [F!1] else XY;return Evaluate(nn,args)/Evaluate(dd,args);end function;
 bm:=hom<B->F|Sub(F!B.1)>;tau:=hom<F->F|bm,Sub(F.1)>;assert tau(tau(tau(F.1))) eq F.1 and tau(tau(tau(u))) eq u;dt:=Differential(tau(u))/du;TM:=Matrix(k,[Eltseq((tau(f)*dt*du)@@om):f in bf]);assert TM^3 eq 1;U:=RowSpace(TM-IdentityMatrix(k,10));
 cu:=MDPlaceCommonZeros(X`_coordinates,qt);ps,es:=Support(FunctionFieldDivisor(Divisor(cu)));assert #ps eq 1;N:=ps[1];assert Degree(N) eq 3;rows:=[* *];
 for i in[1..#rat] do for j in[i..#rat] do D:=Divisor(N)+Divisor(acs[rat[i]])+Divisor(acs[rat[j]]);V,vm:=DifferentialSpace(D);W:=sub<VectorSpace(k,10)|[Eltseq(vm(v)@@om):v in Basis(V)]>;rk:=Dimension(U)-Dimension(U meet W);assert rk le 4;Append(~rows,[*rat[i],rat[j],rk,[Eltseq(v):v in Basis(W)]*]);if rk ne 4 then Append(~bad,[ii,rat[i],rat[j],rk]);end if;end for;end for;
 Append(~out,[*ii,par,EP(N),[EF(tau(v)):v in[F.1,u]],[Eltseq(v):v in Rows(TM)],rows*]);Write(root cat "relative_cubic_rank_p13_partial.m",Sprint(out):Overwrite:=true);print "M318_RELATIVE_CUBIC_RANK",ii,Dimension(U),#rows,#bad,Cputime(tt);
end for;
packet:=[*[ER(c):c in Coefficients(DefiningPolynomial(F))],[EF(f):f in bf],[EP(P):P in acs],ordered,out,bad*];Write(root cat "relative_cubic_rank_p13.m",Sprint(packet):Overwrite:=true);print "D31B_M318_RELATIVE_CUBIC_RANK_P13_COMPLETE",#out,#bad,Cputime(tt);quit;
